      thick: 1.10736,
      spread: 0.5,
      // 뒤끝을 살짝만 둥글린다(재요청): tipPow 1.25 → 0.7 — 지수가 작을수록 끝이 뭉툭하게 닫힌다.
      rootW: 0.06,
